(()=>{
const r=document.getElementById('portfolio');if(!r)return;
const theme=r.querySelector('.theme-toggle');let light=false;try{light=localStorage.getItem('portfolio-theme')==='light';}catch{}
function setTheme(){r.classList.toggle('light',light);document.documentElement.style.colorScheme=light?'light':'dark';document.body.style.background=light?'#fbfcff':'#090c13';theme?.setAttribute('aria-label',light?'Switch to dark theme':'Switch to light theme');theme?.setAttribute('aria-pressed',String(light));}
setTheme();theme?.addEventListener('click',()=>{light=!light;setTheme();try{localStorage.setItem('portfolio-theme',light?'light':'dark');}catch{}});
const systems={api:{nodes:['Client','Spring Boot','AWS ECS'],lines:['$ service.describe()','→ REST endpoints in Spring Boot','→ Built from requirements to deployment','→ Deployed on AWS ECS']},migration:{nodes:['Mainframe','Interfaces','AWS'],lines:['$ migration.plan()','→ Db2 mainframe to Db2 LUW pureScale','→ MQ messaging to Amazon SQS','→ Socket integrations to REST']},delivery:{nodes:['GitHub','Actions','AWS ECS'],lines:['$ pipeline.run()','→ Source changes in GitHub','→ Automated build and deployment','→ Deliver the service to AWS ECS']}};
function system(key){const s=systems[key];r.querySelectorAll('[data-node]').forEach((e,i)=>e.textContent=s.nodes[i]);const text=r.querySelector('.term-text');if(text){text.replaceChildren();s.lines.forEach((l,i)=>{const el=document.createElement(i===0?'b':'span');el.textContent=l;text.append(el);if(i<3)text.append(document.createElement('br'));});}r.querySelectorAll('[data-system]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.system===key)));}
if(r.querySelector('.term-text'))system('api');r.querySelectorAll('[data-system]').forEach(b=>b.addEventListener('click',()=>system(b.dataset.system)));
const toggle=r.querySelector('#detail-toggle'),detail=r.querySelector('#project-detail');toggle?.setAttribute('aria-controls','project-detail');toggle?.addEventListener('click',()=>{detail.hidden=!detail.hidden;toggle.setAttribute('aria-expanded',String(!detail.hidden));toggle.textContent=detail.hidden?'Explore the engineering →':'Close details ↑';});
const input=r.querySelector('#post-search');input?.addEventListener('input',()=>{const q=input.value.toLowerCase().trim();let visible=0;r.querySelectorAll('[data-post]').forEach(e=>{e.hidden=!e.dataset.title.includes(q);if(!e.hidden)visible++;});r.querySelector('#no-results').hidden=visible>0;});
r.querySelectorAll('pre').forEach(pre=>{if(!navigator.clipboard)return;const b=document.createElement('button');b.className='copy-code';b.textContent='Copy';b.setAttribute('aria-label','Copy code');b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(pre.querySelector('code').textContent);b.textContent='Copied ✓';setTimeout(()=>b.textContent='Copy',1800);}catch{b.textContent='Select code to copy';}});pre.prepend(b);});
const progress=r.querySelector('.scroll-progress');function update(){const max=document.documentElement.scrollHeight-innerHeight;progress.style.width=(max>0?scrollY/max*100:0)+'%';}window.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update);update();

const pillars={
 build:{kicker:'01 / Build',title:'Good systems start with clear boundaries.',description:'Translate requirements into Java services, explicit API contracts, and dependable integrations.',tools:['Java','Spring Boot','REST APIs','Microservices','Kafka','Redis','SQL / Db2'],symbol:'{ }',example:'Built a Spring Boot integration microservice from requirements through implementation, replacing legacy socket connections with REST endpoints.',caption:'DELOITTE · APPLICATION MODERNIZATION'},
 deploy:{kicker:'02 / Deploy',title:'Make delivery a repeatable process.',description:'Connect code changes to automated pipelines and containerized services on AWS.',tools:['GitHub Actions','Jenkins','Docker','AWS ECS','Amazon EC2','Amazon SQS'],symbol:'↗',example:'Created GitHub Actions CI/CD pipelines to automate the build and deployment of the integration microservice on AWS ECS.',caption:'DELOITTE · BUILD TO DEPLOYMENT'},
 observe:{kicker:'03 / Observe',title:'Understand what production is telling you.',description:'Connect traces, logs, and metrics to investigate requests, diagnose issues, and understand service behavior.',tools:['OpenTelemetry','Honeycomb','AWS CloudWatch','ECS logs','Datadog','Grafana'],symbol:'◎',example:'Used Honeycomb, OpenTelemetry, CloudWatch, and ECS logs for observability; used Datadog and Grafana to investigate performance issues across services and infrastructure.',caption:'TRACES · LOGS · METRICS'},
 maintain:{kicker:'04 / Maintain',title:'Build for the next change, too.',description:'Keep services understandable and maintainable through clear design, debugging, and thoughtful modernization.',tools:['SOLID principles','Design patterns','Debugging','SIT / UAT','Legacy modernization','Interface integration'],symbol:'↺',example:'Applied SOLID principles and design patterns at PureSoftware, resolved SIT and UAT defects, and modernized legacy interfaces at Deloitte.',caption:'QUALITY · RELIABILITY · EVOLUTION'}
};
const pillarButtons=[...r.querySelectorAll('[data-pillar]')];
function selectPillar(key,focus=false){const p=pillars[key];if(!p)return;pillarButtons.forEach(b=>{const selected=b.dataset.pillar===key;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;if(selected&&focus)b.focus();});const panel=r.querySelector('#pillar-panel');panel.setAttribute('aria-labelledby','pillar-'+key);for(const [id,value] of [['kicker',p.kicker],['title',p.title],['description',p.description],['symbol',p.symbol],['example',p.example],['caption',p.caption]])r.querySelector('#pillar-'+id).textContent=value;const tools=r.querySelector('#pillar-tools');tools.replaceChildren(...p.tools.map((text,i)=>{const el=document.createElement('span');el.className='skill-chip'+(i<2?' featured':'');el.textContent=text;return el;}));}
pillarButtons.forEach((b,i)=>{b.addEventListener('click',()=>selectPillar(b.dataset.pillar));b.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%pillarButtons.length;if(e.key==='ArrowLeft')next=(i-1+pillarButtons.length)%pillarButtons.length;if(e.key==='Home')next=0;if(e.key==='End')next=pillarButtons.length-1;if(next!==undefined){e.preventDefault();selectPillar(pillarButtons[next].dataset.pillar,true);}});});
})();
